/**
 * E-reader sign-ins: username + password for OPDS and KOReader, a URL token for Kobo.
 * Passwords and tokens are generated by the server and shown once; only hashes are stored.
 */
import { createHash, randomBytes, randomInt, timingSafeEqual } from "node:crypto";
import type { FastifyRequest } from "fastify";
import { and, eq, isNull } from "drizzle-orm";
import type { Db } from "../db/client.js";
import { users } from "../db/schema.js";
import { toReader, type Reader } from "../auth/reader.js";
import { sha256 } from "../auth/secrets.js";
import { Lockout, TooManyAttemptsError } from "../auth/rate-limit.js";
import { clientIp } from "../auth/plugin.js";
import { ereaderCredentials } from "./schema.js";

export type CredentialRow = typeof ereaderCredentials.$inferSelect;

export const KOBO_TOKEN_PREFIX = "bbk_";
const LAST_USED_THROTTLE_MS = 5 * 60_000;

/** Lower-case letters and digits without 0/o, 1/l/i: easy to type on an e-ink keyboard. */
const ALPHABET = "23456789abcdefghjkmnpqrstuvwxyz";

/** e.g. "k7qm-4xpa-9hzt-wr3d" (about 79 bits). */
export function generatePassword(): string {
  const groups: string[] = [];
  for (let g = 0; g < 4; g++) {
    let s = "";
    for (let i = 0; i < 4; i++) s += ALPHABET[randomInt(ALPHABET.length)];
    groups.push(s);
  }
  return groups.join("-");
}

export function generateKoboToken(): string {
  // Hex keeps the URL path plain for the Kobo's config file.
  return `${KOBO_TOKEN_PREFIX}${randomBytes(24).toString("hex")}`;
}

export function md5hex(value: string | Buffer): string {
  return createHash("md5").update(value).digest("hex");
}

/** What's stored for a login: KOReader only ever sends md5(password), so hash that. */
export function loginSecretHash(password: string): string {
  return keySecretHash(md5hex(password));
}

function keySecretHash(md5Key: string): string {
  return sha256(`kosync:${md5Key.trim().toLowerCase()}`);
}

export const USERNAME_RE = /^[a-z0-9][a-z0-9._-]{2,31}$/;

export function normalizeUsername(u: string): string {
  return u.trim().toLowerCase();
}

/** A default username from a display name: "Emma Rose" → "emma-rose-x4k9". */
export function suggestUsername(displayName: string): string {
  const base =
    displayName
      .normalize("NFKD")
      .replace(/[̀-ͯ]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 20) || "reader";
  let suffix = "";
  for (let i = 0; i < 4; i++) suffix += ALPHABET[randomInt(ALPHABET.length)];
  return `${base.length < 3 ? `${base}-reader` : base}-${suffix}`;
}

function sameHash(a: string, b: string): boolean {
  const x = Buffer.from(a, "hex");
  const y = Buffer.from(b, "hex");
  return x.length === y.length && x.length > 0 && timingSafeEqual(x, y);
}

export interface EreaderAuth {
  credential: CredentialRow;
  reader: Reader;
}

/** Shared by OPDS, KOReader and Kobo: resolves a credential to the person it acts as. */
export class CredentialStore {
  /** Failed attempts per client IP. Generous: an e-reader retries on its own. */
  readonly lockout: Lockout;

  constructor(
    private readonly db: Db,
    private readonly trustedProxies: string[],
    lockout?: Lockout,
  ) {
    this.lockout = lockout ?? new Lockout({ freeTries: 20, baseLockMs: 60_000 });
  }

  private toAuth(credential: CredentialRow | undefined): EreaderAuth | null {
    if (!credential || credential.revokedAt != null) return null;
    const u = this.db.select().from(users).where(eq(users.id, credential.userId)).get();
    if (!u || u.disabled || u.householdId !== credential.householdId) return null;
    const now = Date.now();
    if (!credential.lastUsedAt || now - credential.lastUsedAt > LAST_USED_THROTTLE_MS) {
      this.db.update(ereaderCredentials).set({ lastUsedAt: now }).where(eq(ereaderCredentials.id, credential.id)).run();
    }
    return { credential, reader: toReader(u) };
  }

  private guard(req: FastifyRequest): string {
    const key = `ereader:${clientIp(req, this.trustedProxies)}`;
    const wait = this.lockout.retryAfter(key);
    if (wait > 0) throw new TooManyAttemptsError(wait);
    return key;
  }

  /** Username plus md5(password) (KOReader's x-auth-key), or a plain password (HTTP Basic). */
  verifyLogin(req: FastifyRequest, username: string, secret: { md5Key: string } | { password: string }): EreaderAuth | null {
    const key = this.guard(req);
    const row = this.db
      .select()
      .from(ereaderCredentials)
      .where(
        and(
          eq(ereaderCredentials.kind, "login"),
          eq(ereaderCredentials.username, normalizeUsername(username)),
          isNull(ereaderCredentials.revokedAt),
        ),
      )
      .get();
    const presented = "md5Key" in secret ? keySecretHash(secret.md5Key) : loginSecretHash(secret.password);
    // Compare against something even when the user doesn't exist, so timing says nothing.
    const ok = sameHash(presented, row?.secretHash ?? sha256("no-such-user"));
    const auth = ok ? this.toAuth(row) : null;
    if (auth) this.lockout.succeed(key);
    else this.lockout.fail(key);
    return auth;
  }

  verifyKoboToken(req: FastifyRequest, token: string): EreaderAuth | null {
    const key = this.guard(req);
    if (!token.startsWith(KOBO_TOKEN_PREFIX)) {
      this.lockout.fail(key);
      return null;
    }
    const row = this.db
      .select()
      .from(ereaderCredentials)
      .where(and(eq(ereaderCredentials.secretHash, sha256(token)), eq(ereaderCredentials.kind, "kobo")))
      .get();
    const auth = this.toAuth(row);
    if (auth) this.lockout.succeed(key);
    else this.lockout.fail(key);
    return auth;
  }
}

/** Parses `Authorization: Basic …`. */
export function basicCredentials(req: FastifyRequest): { username: string; password: string } | null {
  const h = req.headers.authorization;
  const m = h ? /^Basic\s+([A-Za-z0-9+/=]+)\s*$/i.exec(h) : null;
  if (!m) return null;
  const decoded = Buffer.from(m[1]!, "base64").toString("utf8");
  const i = decoded.indexOf(":");
  if (i <= 0) return null;
  return { username: decoded.slice(0, i), password: decoded.slice(i + 1) };
}
